using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using DeliveryService.Mok.Navigation;
namespace DeliveryService.Mok.Editor {
public static class StreetRepairCheck {
 static string log;static void Check(bool ok,string text){log+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Logs/Street-repair-check.txt",log);if(!ok)throw new Exception(text);}
 static IEnumerator Wait(float seconds){float until=Time.time+seconds;while(Time.time<until)yield return null;}
 static void Place(PlayerCombat p,Vector3 at){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=at+Vector3.up*(cc.height*.5f-cc.center.y+.12f);cc.enabled=true;Physics.SyncTransforms();}
 static IEnumerator Key(Key key){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;}
 public static IEnumerator Verify(){
  log="Street repair, pistol and recall integration\n";yield return Wait(.5f);StoryPhoneInbox.Current.AutoOpenEnabled=false;var b=BrokerMission.Current;var p=b.player;var recall=p.GetComponent<BikeRecall>();Check(recall&&recall.bike,"saved owned-bike reference");var phone=UnityEngine.Object.FindFirstObjectByType<PhoneController>();phone.ClosePhone();b.day.pcUIPanel.SetActive(false);Cursor.lockState=CursorLockMode.Locked;
  p.GetComponent<PlayerMove>().enabled=false;var look=p.View.GetComponent<CameraMove>();look.enabled=false;Place(p,b.exit.position);p.View.transform.rotation=Quaternion.LookRotation(Vector3.left);yield return Wait(.3f);
  var weapon=p.GetComponent<PlayerWeapon>();weapon.Equip(WeaponKind.Pistol);yield return null;Check(p.View.GetComponentsInChildren<MeshFilter>().Any(r=>r.name=="M1911"),"held pistol uses asset mesh");Check(p.View.GetComponentsInChildren<Renderer>().Where(r=>r.transform.parent&&r.transform.parent.name=="M1911").All(r=>r.sharedMaterial.shader.name.Contains("Universal Render Pipeline")),"pistol materials support render pipeline");BrokerMissionCheck.Capture(b,"Asset-pistol");
  var bike=recall.bike;var fuel=UnityEngine.Object.FindFirstObjectByType<MotorcycleFuel>();var durability=bike.durabilitySystem;Check(fuel&&durability,"active bike economy components exist");fuel.currentFuel=43;durability.currentDurability=67;var storage=UnityEngine.Object.FindObjectsByType<BikePizzaStorage>(FindObjectsSortMode.None).First(x=>x.bikeController==bike);var cargo=(System.Collections.Generic.List<PizzaData>)typeof(BikePizzaStorage).GetField("storedPizzas",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(storage);var sample=new PizzaData(new(){"도우","소스","치즈"},true);cargo.Add(sample);int cargoCount=storage.StoredCount;int money=MoneyManager.Instance.currentMoney;int bikes=UnityEngine.Object.FindObjectsByType<MotorcycleController>(FindObjectsSortMode.None).Length;
  phone.OpenPhone();yield return null;var planner=UnityEngine.Object.FindFirstObjectByType<NavigationPlanner>();planner.Show(NavigationPlanner.Screen.Home);planner.MoveSelection(-1);Check(planner.Selection==8,"ninth home app selectable");BrokerMissionCheck.Capture(b,"Recall-home");planner.Confirm();Check(planner.CurrentScreen==NavigationPlanner.Screen.Recall,"recall app opens");yield return Key(UnityEngine.InputSystem.Key.Enter);Check(recall.Message.Contains("도착"),"physical Enter calls owned bike");yield return Wait(1);Check(Vector3.Distance(p.transform.position,bike.transform.position)<9,"bike arrives near player");Check(fuel.currentFuel==43&&durability.currentDurability==67&&MoneyManager.Instance.currentMoney==money,"call preserves fuel durability and money");Check(UnityEngine.Object.FindObjectsByType<MotorcycleController>(FindObjectsSortMode.None).Length==bikes,"call does not duplicate bike");Check(storage.StoredCount==cargoCount&&cargo.Contains(sample),"same pizza cargo preserved");BrokerMissionCheck.Capture(b,"Recall-arrived");
  yield return Wait(3);bike.isRefueling=true;Check(!recall.Call(),"refueling blocks recall");bike.isRefueling=false;Time.timeScale=0;Check(!recall.Call(),"pause blocks recall");Time.timeScale=1;
  var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.transform.position=p.transform.position+p.View.transform.forward*4;blocker.transform.localScale=new Vector3(25,10,25);Physics.SyncTransforms();Check(!recall.Call(),"blocked front area does not summon through walls");UnityEngine.Object.Destroy(blocker);yield return null;phone.ClosePhone();
  weapon.Equip(WeaponKind.None);look.enabled=true;p.GetComponent<PlayerMove>().enabled=true;
  yield return SpecialOrderCheck.EdgeCases();Check(true,"repositioned reception retains delivery and retry behavior");
 }
}
}
